package mx.gob.sedesol.basegestor.gestionescolar.v2;

import static org.testng.Assert.assertEquals;
import static org.testng.Assert.assertFalse;
import static org.testng.Assert.assertTrue;

import java.util.ArrayList;
import java.util.Date;
import java.util.List;

import org.testng.annotations.Test;

import mx.gob.sedesol.basegestor.commons.dto.gestionescolar.v2.CausaIndisponibilidadOfertaV2;
import mx.gob.sedesol.basegestor.commons.dto.gestionescolar.v2.CausaPendienteUnidadV2;
import mx.gob.sedesol.basegestor.commons.dto.gestionescolar.v2.CodigoReglaCurricularV2;
import mx.gob.sedesol.basegestor.commons.dto.gestionescolar.v2.CondicionCurricularV2;
import mx.gob.sedesol.basegestor.commons.dto.gestionescolar.v2.ContextoEvaluacionCurricularV2DTO;
import mx.gob.sedesol.basegestor.commons.dto.gestionescolar.v2.EstadoUnidadCurricularV2;
import mx.gob.sedesol.basegestor.commons.dto.gestionescolar.v2.EvaluacionCargaAcademicaV2DTO;
import mx.gob.sedesol.basegestor.commons.dto.gestionescolar.v2.ResultadoEvaluacionCurricularV2DTO;
import mx.gob.sedesol.basegestor.commons.dto.gestionescolar.v2.UnidadEvaluacionCurricularV2DTO;
import mx.gob.sedesol.basegestor.service.impl.gestionescolar.v2.EvaluacionCurricularV2ServiceImpl;

/** F4B-U-01 a F4B-U-27: RN-5.1 consume RN-1.2, RN-6.3 y evaluación de carga. */
public class EvaluacionCurricularV2Fase4BTest {
    private final EvaluacionCurricularV2ServiceImpl service=new EvaluacionCurricularV2ServiceImpl();
    @Test public void f4BU01RegularNoAplica(){assertFalse(e(contexto(obligatoria(1L))).getEvaluacionCargaAcademica().getAplicaRn51());}
    @Test public void f4BU02UnaReprobadaEsRezagoLeve(){EvaluacionCargaAcademicaV2DTO x=e(contexto(reprobada(10L))).getEvaluacionCargaAcademica();assertTrue(x.getAplicaRn51());assertEquals(x.getCondicionRegularizacion(),"REZAGO_LEVE");assertEquals(x.getCargaMaximaNormativa(),Integer.valueOf(6));assertFalse(x.getRn64AplicableEnFuturaFase());}
    @Test public void f4BU03DosReprobadasEsRezagoLeve(){EvaluacionCargaAcademicaV2DTO x=e(contexto(reprobadas(20L,2))).getEvaluacionCargaAcademica();assertTrue(x.getAplicaRn51());assertEquals(x.getUdsReprobadasPrioritarias().size(),2);assertFalse(x.getRn64AplicableEnFuturaFase());}
    @Test public void f4BU04TresReprobadasEsRezagoLeve(){EvaluacionCargaAcademicaV2DTO x=e(contexto(reprobadas(30L,3))).getEvaluacionCargaAcademica();assertTrue(x.getAplicaRn51());assertEquals(x.getCargaMaximaNormativa(),Integer.valueOf(6));assertFalse(x.getRn64AplicableEnFuturaFase());}
    @Test public void f4BU05CuatroReprobadasNoAplicaRn51(){EvaluacionCargaAcademicaV2DTO x=e(contexto(reprobadas(40L,4))).getEvaluacionCargaAcademica();assertFalse(x.getAplicaRn51());assertTrue(x.getRn64AplicableEnFuturaFase());}
    @Test public void f4BU06UnaReprobadaOfertadaEsPrioritaria(){assertTrue(e(contexto(reprobada(50L))).getEvaluacionCargaAcademica().getUdsReprobadasOfertadas().contains(Long.valueOf(50L)));}
    @Test public void f4BU07DosReprobadasOfertadasSonPrioritarias(){assertEquals(e(contexto(reprobadas(60L,2))).getEvaluacionCargaAcademica().getUdsReprobadasOfertadas().size(),2);}
    @Test public void f4BU08TresReprobadasOfertadasSonPrioritarias(){assertEquals(e(contexto(reprobadas(70L,3))).getEvaluacionCargaAcademica().getUdsReprobadasOfertadas().size(),3);}
    @Test public void f4BU09ReprobadaPrecedeObligatorias(){ContextoEvaluacionCurricularV2DTO c=contexto(reprobada(80L));c.getUnidades().addAll(obligatorias(81L,2));EvaluacionCargaAcademicaV2DTO x=e(c).getEvaluacionCargaAcademica();assertTrue(x.getUdsReprobadasPrioritarias().contains(Long.valueOf(80L)));assertEquals(x.getUdsObligatoriasCompatibles().size(),2);}
    @Test public void f4BU10ReprobadaPrecedeOptativas(){ContextoEvaluacionCurricularV2DTO c=contexto(reprobada(90L));c.getUnidades().addAll(optativas(91L,2));EvaluacionCargaAcademicaV2DTO x=e(c).getEvaluacionCargaAcademica();assertTrue(x.getUdsReprobadasPrioritarias().contains(Long.valueOf(90L)));assertEquals(x.getUdsOptativasCompatibles().size(),2);}
    @Test public void f4BU11OrdenRn63SeConserva(){ContextoEvaluacionCurricularV2DTO c=contexto(reprobadas(100L,2));c.getUnidades().add(obligatoria(102L));c.getUnidades().add(optativa(103L));EvaluacionCargaAcademicaV2DTO x=e(c).getEvaluacionCargaAcademica();assertTrue(x.getAplicaRn63());assertEquals(x.getUdsReprobadasPrioritarias().size(),2);assertTrue(x.getUdsObligatoriasCompatibles().contains(Long.valueOf(102L)));assertTrue(x.getUdsOptativasCompatibles().contains(Long.valueOf(103L)));}
    @Test public void f4BU12ReprobadaSinOfertaSeConserva(){UnidadEvaluacionCurricularV2DTO u=reprobada(110L);u.setOfertada(Boolean.FALSE);u.setCausaIndisponibilidadOferta(CausaIndisponibilidadOfertaV2.UD_NO_OFERTADA_PERIODO);EvaluacionCargaAcademicaV2DTO x=e(contexto(u)).getEvaluacionCargaAcademica();assertTrue(x.getAplicaRn51());assertTrue(x.getUdsReprobadasNoDisponibles().contains(Long.valueOf(110L)));assertTrue(x.getCausasIndisponibilidadRegularizacion().toString().contains("SIN_OFERTA"));}
    @Test public void f4BU13SinCupoSeDistingue(){UnidadEvaluacionCurricularV2DTO u=reprobada(120L);u.setCupoDisponibleConocido(Boolean.FALSE);u.setCausaIndisponibilidadOferta(CausaIndisponibilidadOfertaV2.SIN_CUPO);EvaluacionCargaAcademicaV2DTO x=e(contexto(u)).getEvaluacionCargaAcademica();assertTrue(x.getCausasIndisponibilidadRegularizacion().toString().contains("SIN_CUPO"));assertFalse(x.getCausasIndisponibilidadRegularizacion().toString().contains("SIN_OFERTA"));}
    @Test public void f4BU14PosteriorSeriadaNoEsCompatible(){UnidadEvaluacionCurricularV2DTO posterior=obligatoria(131L);posterior.setSeriacionDirectaConocida(Boolean.TRUE);EvaluacionCargaAcademicaV2DTO x=e(contexto(reprobada(130L),posterior)).getEvaluacionCargaAcademica();assertFalse(x.getUdsObligatoriasCompatibles().contains(Long.valueOf(131L)));}
    @Test public void f4BU15TresIntentosSonUnaReprobada(){UnidadEvaluacionCurricularV2DTO u=reprobada(140L);u.setIntentosFallidosHistoricosConfiables(Integer.valueOf(3));assertEquals(e(contexto(u)).getCantidadReprobadasVigentes(),Integer.valueOf(1));}
    @Test public void f4BU16BajaParcialNoIncrementaReprobadas(){UnidadEvaluacionCurricularV2DTO u=obligatoria(150L);u.setEstado(EstadoUnidadCurricularV2.BAJA_PARCIAL);u.setCausa(CausaPendienteUnidadV2.BAJA_PARCIAL);EvaluacionCargaAcademicaV2DTO x=e(contexto(reprobada(151L),u)).getEvaluacionCargaAcademica();assertTrue(x.getAplicaRn51());assertEquals(x.getUdsReprobadasPrioritarias().size(),1);}
    @Test public void f4BU17NoCursadaNoIncrementaReprobadas(){EvaluacionCargaAcademicaV2DTO x=e(contexto(reprobada(160L),obligatoria(161L))).getEvaluacionCargaAcademica();assertTrue(x.getAplicaRn51());assertEquals(x.getUdsReprobadasPrioritarias().size(),1);}
    @Test public void f4BU18TresReprobadasMasCandidatasRespetanMaximoSeis(){ContextoEvaluacionCurricularV2DTO c=contexto(reprobadas(170L,3));c.getUnidades().addAll(obligatorias(173L,4));EvaluacionCargaAcademicaV2DTO x=e(c).getEvaluacionCargaAcademica();assertEquals(x.getCargaMaximaNormativa(),Integer.valueOf(6));assertFalse(x.getMaximoCumplido());}
    @Test public void f4BU19QuintoDesde2027DetectaRn61(){ContextoEvaluacionCurricularV2DTO c=contexto(reprobada(180L));c.setSemestreObjetivo(Integer.valueOf(5));c.setPeriodoNormativo("2027-1");assertTrue(e(c).getEvaluacionCargaAcademica().getCtr01Rn61Procedente());}
    @Test public void f4BU20TerceroNoDetectaRn61(){ContextoEvaluacionCurricularV2DTO c=contexto(reprobada(190L));c.setPeriodoNormativo("2027-1");assertFalse(e(c).getEvaluacionCargaAcademica().getCtr01Rn61Procedente());}
    @Test public void f4BU21SeptimoNoDetectaRn61(){ContextoEvaluacionCurricularV2DTO c=contexto(reprobada(200L));c.setSemestreObjetivo(Integer.valueOf(7));c.setPeriodoNormativo("2027-1");assertFalse(e(c).getEvaluacionCargaAcademica().getCtr01Rn61Procedente());}
    @Test public void f4BU22UnaDeDosAcreditadaMantieneRezagoLeve(){EvaluacionCargaAcademicaV2DTO x=e(contexto(reprobada(210L),acreditada(211L))).getEvaluacionCargaAcademica();assertTrue(x.getAplicaRn51());assertEquals(x.getUdsReprobadasPrioritarias().size(),1);}
    @Test public void f4BU23UltimaAcreditadaDejaDeAplicar(){EvaluacionCargaAcademicaV2DTO x=e(contexto(acreditada(220L))).getEvaluacionCargaAcademica();assertFalse(x.getAplicaRn51());assertEquals(x.getCondicionRegularizacion(),"NO_APLICA");}
    @Test public void f4BU24NoDeterminadoRequiereRevision(){EvaluacionCargaAcademicaV2DTO x=e(contexto(indeterminada(230L))).getEvaluacionCargaAcademica();assertFalse(x.getAplicaRn51());assertEquals(x.getCondicionRegularizacion(),"NO_DETERMINADA");assertTrue(x.getRequiereRevision());}
    @Test public void f4BU25DuplicadoNoDuplicaConteo(){UnidadEvaluacionCurricularV2DTO a=reprobada(240L),b=reprobada(240L);a.setBloque("B1");b.setBloque("B2");assertEquals(e(contexto(a,b)).getCantidadReprobadasVigentes(),Integer.valueOf(1));}
    @Test public void f4BU26MismoContextoEsDeterminista(){ContextoEvaluacionCurricularV2DTO c=contexto(reprobada(250L));assertEquals(e(c).getEvaluacionCargaAcademica().getCondicionRegularizacion(),e(c).getEvaluacionCargaAcademica().getCondicionRegularizacion());}
    @Test public void f4BU27NoEfectoProductivoYTraza(){UnidadEvaluacionCurricularV2DTO u=reprobada(260L);ResultadoEvaluacionCurricularV2DTO r=e(contexto(u));assertFalse(r.getEfectosProductivosAplicados());assertTrue(u.getOfertada());assertTrue(r.getReglasEvaluadas().contains(CodigoReglaCurricularV2.RN_5_1));assertTrue(r.getCondicionesDetectadas().contains(CondicionCurricularV2.REZAGO_LEVE));}
    private ResultadoEvaluacionCurricularV2DTO e(ContextoEvaluacionCurricularV2DTO c){return service.evaluarSombra(c);} private ContextoEvaluacionCurricularV2DTO contexto(UnidadEvaluacionCurricularV2DTO...us){ContextoEvaluacionCurricularV2DTO c=new ContextoEvaluacionCurricularV2DTO();c.setVersionReglas("PE2027-V1");c.setFechaEvaluacion(new Date(0L));c.setSemestreObjetivo(Integer.valueOf(3));c.setActividadAcademicaComprobada(Boolean.TRUE);c.setPermanenciaDentroLimiteComprobada(Boolean.TRUE);c.setDictaminacionEgresoConocida(Boolean.TRUE);c.setOportunidadesMejoraUtilizadas(Integer.valueOf(0));for(UnidadEvaluacionCurricularV2DTO u:us)c.getUnidades().add(u);return c;} private ContextoEvaluacionCurricularV2DTO contexto(List<UnidadEvaluacionCurricularV2DTO> us){return contexto(us.toArray(new UnidadEvaluacionCurricularV2DTO[us.size()]));}
    private List<UnidadEvaluacionCurricularV2DTO> obligatorias(Long i,int n){return unidades(i,n,"Obligatoria");} private List<UnidadEvaluacionCurricularV2DTO> optativas(Long i,int n){return unidades(i,n,"Optativa");} private List<UnidadEvaluacionCurricularV2DTO> reprobadas(Long i,int n){List<UnidadEvaluacionCurricularV2DTO> r=new ArrayList<UnidadEvaluacionCurricularV2DTO>();for(int x=0;x<n;x++)r.add(reprobada(Long.valueOf(i.longValue()+x)));return r;} private List<UnidadEvaluacionCurricularV2DTO> unidades(Long i,int n,String t){List<UnidadEvaluacionCurricularV2DTO> r=new ArrayList<UnidadEvaluacionCurricularV2DTO>();for(int x=0;x<n;x++)r.add(pendiente(Long.valueOf(i.longValue()+x),t));return r;}
    private UnidadEvaluacionCurricularV2DTO obligatoria(Long i){return pendiente(i,"Obligatoria");} private UnidadEvaluacionCurricularV2DTO optativa(Long i){return pendiente(i,"Optativa");} private UnidadEvaluacionCurricularV2DTO reprobada(Long i){UnidadEvaluacionCurricularV2DTO u=pendiente(i,"Obligatoria");u.setEstado(EstadoUnidadCurricularV2.REPROBADA);u.setCausa(CausaPendienteUnidadV2.REPROBACION);u.setReprobacionVigenteConocida(Boolean.TRUE);u.setReprobacionPeriodoPrevioConocida(Boolean.TRUE);return u;} private UnidadEvaluacionCurricularV2DTO acreditada(Long i){UnidadEvaluacionCurricularV2DTO u=pendiente(i,"Obligatoria");u.setEstado(EstadoUnidadCurricularV2.ACREDITADA);u.setCausa(null);return u;} private UnidadEvaluacionCurricularV2DTO indeterminada(Long i){UnidadEvaluacionCurricularV2DTO u=pendiente(i,"Obligatoria");u.setEstado(EstadoUnidadCurricularV2.NO_DETERMINADO);u.setCausa(null);return u;} private UnidadEvaluacionCurricularV2DTO pendiente(Long i,String t){UnidadEvaluacionCurricularV2DTO u=new UnidadEvaluacionCurricularV2DTO();u.setIdPrograma(i);u.setClave("UD"+i);u.setTipoUd(t);u.setEstado(EstadoUnidadCurricularV2.NO_CURSADA);u.setCausa(CausaPendienteUnidadV2.NO_CURSAMIENTO);u.setOfertada(Boolean.TRUE);u.setGrupoActivoConocido(Boolean.TRUE);u.setCupoDisponibleConocido(Boolean.TRUE);u.setSeleccionableOrigen(Boolean.TRUE);return u;}
}
